-- identity.0001_initial: generated by makemigrations. Review before committing.
CREATE TABLE identity_accounts (
    id uuid NOT NULL,
    actor_id uuid NOT NULL,
    email text NOT NULL CONSTRAINT identity_accounts_email_check CHECK (char_length(email) BETWEEN 3 AND 254),
    password_hash text CONSTRAINT identity_accounts_password_hash_check CHECK (char_length(password_hash) BETWEEN 1 AND 512),
    failed_logins integer NOT NULL DEFAULT 0 CONSTRAINT identity_accounts_failed_logins_check CHECK (failed_logins >= 0),
    locked_until timestamptz,
    disabled_at timestamptz,
    password_changed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (id),
    CONSTRAINT identity_accounts_email_key UNIQUE (email),
    CONSTRAINT identity_accounts_actor_key UNIQUE (actor_id)
);
CREATE TABLE identity_account_tokens (
    id uuid NOT NULL,
    account_id uuid NOT NULL REFERENCES identity_accounts (id),
    purpose text NOT NULL CONSTRAINT identity_account_tokens_purpose_check CHECK (purpose IN ('invite', 'reset')),
    token_hash text NOT NULL CONSTRAINT identity_account_tokens_token_hash_check CHECK (char_length(token_hash) BETWEEN 64 AND 64),
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    used_at timestamptz,
    PRIMARY KEY (id),
    CONSTRAINT identity_account_tokens_token_hash_key UNIQUE (token_hash)
);
CREATE INDEX identity_account_tokens_account_idx ON identity_account_tokens (account_id);
CREATE TABLE identity_logins (
    id uuid NOT NULL,
    state_hash text NOT NULL CONSTRAINT identity_logins_state_hash_check CHECK (char_length(state_hash) BETWEEN 64 AND 64),
    nonce text NOT NULL CONSTRAINT identity_logins_nonce_check CHECK (char_length(nonce) BETWEEN 43 AND 43),
    verifier text NOT NULL CONSTRAINT identity_logins_verifier_check CHECK (char_length(verifier) BETWEEN 43 AND 43),
    return_to text NOT NULL CONSTRAINT identity_logins_return_to_check CHECK (char_length(return_to) BETWEEN 1 AND 2048),
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    PRIMARY KEY (id),
    CONSTRAINT identity_logins_state_hash_key UNIQUE (state_hash)
);
CREATE INDEX identity_logins_expires_idx ON identity_logins (expires_at);
CREATE TABLE identity_sessions (
    id uuid NOT NULL,
    token_hash text NOT NULL CONSTRAINT identity_sessions_token_hash_check CHECK (char_length(token_hash) BETWEEN 64 AND 64),
    actor_id uuid NOT NULL,
    created_at timestamptz NOT NULL DEFAULT now(),
    expires_at timestamptz NOT NULL,
    last_seen_at timestamptz NOT NULL DEFAULT now(),
    revoked_at timestamptz,
    PRIMARY KEY (id),
    CONSTRAINT identity_sessions_token_hash_key UNIQUE (token_hash)
);
CREATE INDEX identity_sessions_actor_idx ON identity_sessions (actor_id);
CREATE INDEX identity_sessions_expires_idx ON identity_sessions (expires_at);
